icons"></i> Favicon<small>SVG, PNG o ICO</small><input name="favicon" type="file" accept="image/*,.ico,.svg" hidden></label><label class="upload-zone" tabindex="0"><i class="fa-solid fa-right-to-bracket"></i> Imagen de inicio de sesión<small>PNG, JPG o WEBP</small><input name="login_image" type="file" accept="image/*" hidden></label></div></section><section class="panel spaced" id="experience"><div class="panel-head"><div><b>Experiencia</b><small>Preferencias de interfaz.</small></div></div><div class="settings-grid"><div class="field"><label>Tema</label><select name="theme" class="select2"><option value="system" <?=($pref['theme']??'system')==='system'?'selected':''?>>Sistema</option><option value="light" <?=($pref['theme']??'')==='light'?'selected':''?>>Claro</option><option value="dark" <?=($pref['theme']??'')==='dark'?'selected':''?>>Oscuro</option></select></div><div class="field"><label>Ayuda contextual</label><label class="switch-line"><input name="context_help" type="checkbox" <?=!empty($pref['context_help'])?'checked':''?>><span></span> Mostrar ayudas</label></div></div><div class="form-actions-sticky"><button class="primary"><i class="fa-solid fa-floppy-disk"></i> Guardar cambios</button><small>Los cambios se aplican a esta empresa.</small></div></section></form>
